  function appendInline(node,value){const text=String(value||''),pattern=/(\*\*[^*\n]+\*\*|`[^`\n]+`|\[[^\]\n]+\]\(https:\/\/[^\s)]+\)|\[S\d{1,4}\])/g;let at=0;for(const match of text.matchAll(pattern)){node.append(document.createTextNode(text.slice(at,match.index)));const raw=match[0];let child;if(raw.startsWith('**')){child=document.createElement('strong');child.textContent=raw.slice(2,-2);}else if(raw.startsWith('`')){child=document.createElement('code');child.textContent=raw.slice(1,-1);}else if(/^\[S\d{1,4}\]$/.test(raw)){const id=raw.slice(1,-1);if(list(project?.artifact?.sources).some(source=>source.id===id)){child=document.createElement('a');child.href='#learning-source-'+id;child.textContent=raw;}}else{const link=raw.match(/^\[([^\]]+)\]\((.+)\)$/),url=link&&L.safeURL(link[2]);if(url){child=document.createElement('a');child.href=url;child.target='_blank';child.rel='noopener noreferrer';child.textContent=link[1];}}node.append(child||document.createTextNode(raw));at=match.index+raw.length;}node.append(document.createTextNode(text.slice(at)));}
  function renderOutput(value){const target=$('learning-result-content');target.replaceChildren();const lines=String(value||'').split('\n');let paragraph=[],code=null,group=null;const flush=()=>{if(paragraph.length){const node=document.createElement('p');appendInline(node,paragraph.join('\n'));target.append(node);paragraph=[];}group=null;};for(const line of lines){if(/^\s*```/.test(line)){flush();if(code){target.append(code);code=null;}else code=document.createElement('pre');continue;}if(code){code.textContent+=(code.textContent?'\n':'')+line;continue;}const heading=line.match(/^#{1,6}\s+(.+)$/),bullet=line.match(/^\s*[-*]\s+(.+)$/),ordered=line.match(/^\s*\d+[.)]\s+(.+)$/);if(heading){flush();const node=document.createElement('h4');appendInline(node,heading[1]);target.append(node);}else if(bullet||ordered){if(paragraph.length)flush();const tag=ordered?'OL':'UL';if(!group||group.tagName!==tag){group=document.createElement(tag.toLowerCase());target.append(group);}const node=document.createElement('li');appendInline(node,(bullet||ordered)[1]);group.append(node);}else if(!line.trim())flush();else{group=null;paragraph.push(line);}}flush();if(code)target.append(code);}
  function renderSources(values){const target=$('learning-sources'),sources=list(values);target.hidden=!sources.length;if(!sources.length){target.replaceChildren();return;}target.innerHTML='<h4>Sources &amp; evidence</h4><ol>'+sources.map(source=>{const url=L.safeURL(source.url);return'<li'+(source.id?' id=\"learning-source-'+e(source.id)+'\"':'')+'>'+(url?'<a href="'+e(url)+'" target="_blank" rel="noopener noreferrer">'+e(source.title||url)+'</a>':e(source.title||'Source'))+(source.excerpt?'<p>'+e(source.excerpt)+'</p>':'')+'</li>';}).join('')+'</ol>';}
