  function renderSourceChecks(value){const target=$('learning-source-checks');target.hidden=!value;target.replaceChildren();if(!value)return;const overlaps=list(value.overlaps),needsAttention=overlaps.filter(item=>item.needsAttribution),sources=list(value.checkedSources);target.innerHTML='<details><summary>Source checks'+(needsAttention.length?' · '+needsAttention.length+' '+(needsAttention.length===1?'passage':'passages')+' to review':'')+'</summary><p class="learning-small">'+e(value.coverage||'Compared the supplied source passages and citation markers.')+'</p>'+(needsAttention.length?'<ul class="learning-overlaps">'+needsAttention.map(item=>'<li><strong>'+e(item.sourceId||'Source')+'</strong><blockquote>'+e(item.text||'')+'</blockquote><p>'+e(item.note||'Review quotation marks and attribution for this passage.')+'</p></li>').join('')+'</ul>':'')+(sources.length?'<ul>'+sources.map(item=>'<li><strong>'+e(item.id||'Source')+'</strong> · '+e(item.status==='retrieved'?'Public text retrieved':item.status==='provided'?'Supplied passage compared':item.status==='unavailable'?'Public text unavailable':'Link recorded; public text not retrieved')+'</li>').join('')+'</ul>':'')+'<p class="learning-small">This checks source links, citation markers and matching wording within the compared material. It does not establish complete originality or independently verify every claim.</p></details>';}
  function renderCards(artifact){const target=$('learning-study-cards'),cards=list(artifact.cards||artifact.flashcards),quiz=list(artifact.quiz||artifact.practiceQuestions),slides=list(artifact.slides);target.hidden=!cards.length&&!quiz.length&&!slides.length;target.replaceChildren();for(const [index,item]of cards.entries()){const card=document.createElement('div');card.className='learning-study-card';const question=document.createElement('p');question.textContent=String(item.front||item.question||'Flashcard '+(index+1));card.append(question);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Reveal answer';details.append(summary);const answer=document.createElement('p');answer.textContent=String(item.back||item.answer||'');details.append(answer);card.append(details);target.append(card);}for(const [index,item]of quiz.entries()){const card=document.createElement('form');card.className='learning-study-card learning-quiz-question';const fieldset=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=String(item.question||item.prompt||'Practice '+(index+1));fieldset.append(legend);const choices=list(item.choices||item.options);for(const [choiceIndex,value]of choices.entries()){const label=document.createElement('label'),input=document.createElement('input');label.className='learning-quiz-choice';input.type='radio';input.name='answer-'+index;input.value=String(choiceIndex);input.required=true;label.append(input,document.createTextNode(String(value)));fieldset.append(label);}card.append(fieldset);const answerIndex=Number.isInteger(item.answerIndex)&&item.answerIndex>=0&&item.answerIndex<choices.length?item.answerIndex:null;if(choices.length&&answerIndex!==null){const check=document.createElement('button');check.type='submit';check.className='ds-btn ds-btn-secondary';check.textContent='Check my answer';card.append(check);const feedback=document.createElement('p');feedback.className='learning-quiz-feedback';feedback.setAttribute('role','status');feedback.hidden=true;card.append(feedback);card.addEventListener('submit',event=>{event.preventDefault();if(!card.reportValidity())return;const selected=Number(new FormData(card).get('answer-'+index)),correct=selected===answerIndex;feedback.hidden=false;feedback.dataset.correct=String(correct);feedback.textContent=(correct?'That’s right. ':'The expected answer is “'+choices[answerIndex]+'”. ')+(item.explanation||'');});}else{const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Show answer & explanation';details.append(summary);const answer=document.createElement('p');answer.textContent=String(item.answer||item.explanation||'');details.append(answer);card.append(details);}target.append(card);}for(const [index,item]of slides.entries()){const card=document.createElement('section');card.className='learning-study-card';const title=document.createElement('h4');title.textContent=(index+1)+'. '+String(item.title||'Slide');card.append(title);const bullets=document.createElement('ul');for(const value of list(item.bullets)){const li=document.createElement('li');li.textContent=String(value);bullets.append(li);}card.append(bullets);if(item.speakerNotes){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Speaker notes';const notes=document.createElement('p');notes.textContent=String(item.speakerNotes);details.append(summary,notes);card.append(details);}target.append(card);}}
