  function renderActions(){const kind=project.kind,artifact=project.artifact||{},hasContent=Boolean(artifact.content);let actions=[];if(kind==='writing'){actions=[['plan',hasContent?'Revisit my approach':'Develop my approach'],['draft','Build my draft'],['review','Review against my rubric']];}else if(kind==='study')actions=[['study','Explain this'],['quiz','Practice what I learned'],['flashcards','Make flashcards']];else if(kind==='quiz')actions=[['quiz','Build a practice quiz'],['study','Explain the concepts'],['flashcards','Make flashcards']];else if(kind==='flashcards')actions=[['flashcards','Make flashcards'],['quiz','Practice with a quiz']];else if(kind==='presentation')actions=[['plan','Plan my presentation'],['presentation','Build my presentation'],['review','Review my presentation']];else if(kind==='discussion')actions=[['plan','Develop my response'],['discussion','Build from my ideas'],['review','Review my response']];$('learning-run-actions').innerHTML=actions.map(([action,label],index)=>'<button type="button" data-run-action="'+action+'" class="ds-btn '+(index===0&&!hasContent?'ds-btn-primary':'ds-btn-secondary')+'">'+label+'</button>').join('');}
  function renderSteps(){const target=$('learning-project-steps'),writing=['writing','presentation','discussion'].includes(project.kind);target.hidden=!writing;if(!writing){target.replaceChildren();return;}const action=project.artifact?.action,index=action==='review'?2:['draft','presentation','discussion'].includes(action)?1:0;target.innerHTML=['Develop an approach','Build from your ideas','Review the work'].map((label,i)=>'<li'+(i===index?' aria-current="step"':'')+' data-step-state="'+(i<index?'previous':i===index?'current':'next')+'">'+label+'</li>').join('');}
